import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as u,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"报价与撤单博弈","description":"","frontmatter":{"title":"报价与撤单博弈","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/quote-cancellation-game.md","filePath":"quant/quote-cancellation-game.md","lastUpdated":1789023840000}'),h={name:"quant/quote-cancellation-game.md"};function p(m,a,E,f,_,B){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="报价与撤单博弈" tabindex="-1">报价与撤单博弈 <a class="header-anchor" href="#报价与撤单博弈" aria-label="Permalink to &quot;报价与撤单博弈&quot;">​</a></h1><div class="epigraph"><p>电子簿上大多数限价单不会活到成交。撤单与改价是策略，不是系统故障：它缩短被捡窗口，也制造别人必须应对的闪烁深度。</p><footer>—— Hasbrouck and Saar, Technology and liquidity provision: The blurring of traditional definitions, Journal of Financial Markets, 2013</footer></div><p><a href="/quant/hidden-liquidity-theory">隐藏流动性</a>改变事前可见量。缺口是时间维：可见的报价可以在成交前被撤走。Hasbrouck 与 Saar 记录低延迟环境下订单寿命变短、传统「挂单=提供流动性」被模糊。Foucault、Kozhan 与 Tham（2017）把有毒套利与过时报价的撤单竞赛写进理论。本课写撤单作为均衡策略，不为后文报价填塞预支操纵定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Foucault 的限价是一份直到下一期才被捡的期权。若允许连续撤单，期权寿命变成选择变量：寿命短，被捡降、非执行升，且必须付消息与排队重置成本（FIFO 下改价常等于撤旧加新）。问题是最优寿命与最优报价如何联立，以及当许多人高频撤单时，可见深度还有没有 Grossman–Miller 意义上的「在场」。</p><p>另一面：你的撤单是别人的状态冲击。虚假的厚深度诱使市价进入，随即撤走，对方打穿。这在后文幌骚课会升级为操纵意图；本课先承认即使没有操纵意图，理性被捡规避也会产生极高撤单率。</p><h3 id="快相对慢挂单者" tabindex="-1">快相对慢挂单者 <a class="header-anchor" href="#快相对慢挂单者" aria-label="Permalink to &quot;快相对慢挂单者&quot;">​</a></h3><p>van Kervel（2015）等强调多市场：快的人在一处成交后立刻撤其他场所的报价，慢的挂单被留下当被捡对象。撤单博弈因此是速度博弈。Budish 的狙击是同一结构的吃单侧；本课是挂单侧的对称动作——谁先撤过时报价。</p><p><span class="marginnote">统计上撤单率高不等于市场「假」。许多撤单是做市商把库存偏度或信念更新写进报价。要用随后是否重新挂在附近，区分更新与一去不返的撤退。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把限价寿命 \\(\\tau\\) 放进上一课的效用：\\(\\pi(\\tau)\\)、被捡 \\(E[V\\mid\\mathrm{fill},\\tau]\\) 都随 \\(\\tau\\) 变。消息强度高时最优 \\(\\tau\\) 缩短。技术降低改价成本，均衡寿命下降，成交/消息比下降。Hasbrouck–Saar 称之为流动性供给定义的模糊：大量订单从不意图等到自然成交。</p><p>均衡反馈：若所有做市商 \\(\\tau\\) 极短，市价单面对的有效深度下降，有效价差上升，又会吸引更短 \\(\\tau\\) 的人用速度赚钱。这是军备竞赛的挂单版，频繁批量拍卖课将从设计上切断。</p><h3 id="与库存偏度的关系" tabindex="-1">与库存偏度的关系 <a class="header-anchor" href="#与库存偏度的关系" aria-label="Permalink to &quot;与库存偏度的关系&quot;">​</a></h3><p>Ho–Stoll 的偏度可以通过撤一侧、加另一侧实现。高频下这表现为一侧闪烁。信息更新同样表现为双侧同时撤再重挂更宽。经验分离：库存型撤单不对称且随后中点随库存回复；信息型撤单对称加宽且中点永久移动。</p>',14)),(e(),s(c,null,{default:o(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20News%5B%22%E5%85%AC%E5%85%B1%E4%BF%A1%E6%81%AF%20%2F%20%E4%BB%96%E5%A4%84%E6%88%90%E4%BA%A4%22%5D%20--%3E%20Race%5B%22%E6%92%A4%E8%BF%87%E6%97%B6%E6%8A%A5%E4%BB%B7%20vs%20%E8%A2%AB%E5%90%83%22%5D%0A%20%20Tau%5B%22%E9%80%89%E6%8B%A9%E5%AF%BF%E5%91%BD%20%CF%84%22%5D%20--%3E%20Race%0A%20%20Race%20--%3E%20Eff%5B%22%E6%9C%89%E6%95%88%E6%B7%B1%E5%BA%A6%E4%B8%8E%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Eff%20--%3E%20Tau%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>撤单把「在场」从存量改成流量。Grossman–Miller 的 \\(M\\) 个做市商在场，变成 \\(M\\) 个愿意在未来 \\(\\tau\\) 毫秒内在场的过程。冲击 \\(z\\) 来时，若 \\(\\tau\\) 短于冲击被识别的时间，暂时折让可以变得极大——供给在需要它时消失。这是后文做市义务与闪电崩盘的理论接口。</p><p>对 Hasbrouck VAR：报价新息大量来自无成交的改价，信息含量不全在 \\(q\\) 里。只把成交当信息会低估发现速度。报价过程必须进系统，这正是 1991 年文章把报价与成交放在一起的先见。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>把所有短寿命单叫做操纵，在法律与经济上都过宽。操纵需要误导意图与虚假供给，见幌骚课。交易所的最小寿命、撤单费率、订单消息比限制，是直接对 \\(\\tau\\) 征税，会改变均衡，也有把做市赶出明簿的风险。数据档位若只有快照，会完全看不见撤单博弈。</p><p><span class="marginnote">回测若假设「当时挂着就能吃到」，在高撤单市场是最常见的幻觉。可成交性必须用事件流与撮合规则重建，不能用 Level-1 快照。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>撤单缩短被捡窗口，也缩短有效在场时间；高撤单率可以是理性做市，不必先贴操纵标签。</li><li>寿命 \\(\\tau\\) 与报价联立，技术降低改价成本会推高消息/成交比。</li><li>快者撤跨市场过时报价，慢挂单者承担被捡。</li><li>出处：Hasbrouck and Saar, <em>Journal of Financial Markets</em>, 2013；Foucault, Kozhan and Tham, <em>Review of Financial Studies</em>, 2017；van Kervel, <em>Review of Financial Studies</em>, 2015。</li></ul>',8))])}const b=r(h,[["render",p]]);export{A as __pageData,b as default};
